package org.pms.silverocean.service.estateops;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import org.pms.silverocean.database.pms.*;import org.pms.silverocean.database.pms.entities.*;import org.pms.silverocean.service.PMSCustomException;import org.pms.silverocean.service.auth.dao.UserDao;import org.pms.silverocean.service.auth.roles.enums.PMSRole;import java.time.ZonedDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class EstateOperationsServiceTest{@Mock EstateBudgetRepo budgets;@Mock EstateBudgetLineRepo lines;@Mock EstateMeetingRepo meetings;@Mock EstateResolutionRepo resolutions;@Mock EstateWorkOrderRepo works;@Mock PropertyRepo properties;@Mock UserDao users;EstateOperationsService service;Property property;
 @BeforeEach void setup(){service=new EstateOperationsService(budgets,lines,meetings,resolutions,works,properties,users);property=new Property();property.setId(4L);property.setActive(true);when(users.getUserId()).thenReturn(2L);when(users.getActiveRole()).thenReturn(PMSRole.ESTATE_MANAGER);when(properties.findByIdAndStaffOrOwner(4L,2L)).thenReturn(Optional.of(property));}
 @Test void emptyBudgetCannotBeApproved(){EstateBudget b=new EstateBudget();b.setId(7L);b.setPropertyId(4);b.setStatus("DRAFT");b.setActive(true);when(budgets.findById(7L)).thenReturn(Optional.of(b));when(lines.findAllByBudgetIdAndActiveTrueOrderById(7L)).thenReturn(List.of());assertThrows(PMSCustomException.class,()->service.approve(7L));}
 @Test void meetingRequiresQuorumAndMinutes(){EstateMeeting m=new EstateMeeting();m.setId(8L);m.setPropertyId(4);m.setStatus("SCHEDULED");m.setQuorumRequired(5);m.setActive(true);when(meetings.findById(8L)).thenReturn(Optional.of(m));var update=new EstateOperationsModels.MeetingUpdate(EstateOperationsModels.MeetingStatus.HELD,4,"Minutes");assertThrows(PMSCustomException.class,()->service.updateMeeting(8L,update));}
 @Test void completedWorkOrderCannotReopen(){EstateWorkOrder w=new EstateWorkOrder();w.setId(9L);w.setPropertyId(4);w.setStatus("COMPLETED");w.setActive(true);when(works.findById(9L)).thenReturn(Optional.of(w));var update=new EstateOperationsModels.WorkUpdate(EstateOperationsModels.WorkStatus.OPEN,null,ZonedDateTime.now(),null,null,null);assertThrows(PMSCustomException.class,()->service.updateWork(9L,update));}
}
